 34	        self.infinity
 35	    }
 36	    
 37	    /// Convert to the pk2sk point format (Option<(U256, U256)>)
 38	    fn to_pk2sk_point(&self) -> Option<(U256, U256)> {
 39	        if self.infinity {
 40	            None
 41	        } else {
 42	            Some((self.x.clone(), self.y.clone()))
 43	        }
 44	    }
 45	    
 46	    /// Create an EcPoint from a pk2sk point format
 47	    fn from_pk2sk_point(point: Option<(U256, U256)>) -> Self {
 48	        match point {
 49	            None => Self::infinity(),
 50	            Some((x, y)) => Self { x, y, infinity: false },
 51	        }
