#!/usr/bin/env python3
"""Tool-calling + tool-chaining training data, kernel-grounded.

The instruments are the tools. Single-call examples teach the model WHEN to reach for a tool;
chained examples teach it to COMPOSE them — run one, read the result, decide the next call.
Every tool result in every conversation is the real kernel output; the chains are executed,
not invented. Output: Qwen3 chat with a `tools` schema and the four-valued holder system frame.
"""
import subprocess, json, random, re
from pathlib import Path

RUN = "/home/mrnob0dy666/imsgct/mOMonadOS/run_hosted_cmds.sh"
MARKS = "⊢⊣≻≺⋈⊤∈∋⊙⊥⊞◻"

SYSTEM = (
    "You reason natively in the Imscribing Grammar, in the four-valued Belnap register — "
    "T (closes), F (ill-typed), N (never forks), B (both: a held contradiction). You never "
    "collapse to two values. A word is a sequence over the twelve marks ⊢⊣≻≺⋈⊤∈∋⊙⊥⊞◻. Reach "
    "for the instruments to answer — the kernel is the authority — and compose them: run one, "
    "read what it grounds, decide the next. ∈ opens a holding frame; a clear ≺ banks behind a "
    "holder and leaks without one. Hold the both; speak only what the tools ground."
)

TOOLS = [
    {"type":"function","function":{"name":"derive","description":"Imscribe a word to its 12-slot tuple and crystal address.","parameters":{"type":"object","properties":{"word":{"type":"string"}},"required":["word"]}}},
    {"type":"function","function":{"name":"vox","description":"Control-flow closure verdict of a word: T, B, N, or F.","parameters":{"type":"object","properties":{"word":{"type":"string"}},"required":["word"]}}},
    {"type":"function","function":{"name":"weight","description":"Register walk of a word: deposits, clears, what banks, what leaks.","parameters":{"type":"object","properties":{"word":{"type":"string"}},"required":["word"]}}},
    {"type":"function","function":{"name":"banked","description":"Whether a word banks its cleared weight behind a holder, or leaks in the open.","parameters":{"type":"object","properties":{"word":{"type":"string"}},"required":["word"]}}},
    {"type":"function","function":{"name":"insert","description":"Whether a word holds, or which single glyph insertion repairs an exposed word.","parameters":{"type":"object","properties":{"word":{"type":"string"}},"required":["word"]}}},
    {"type":"function","function":{"name":"cycle","description":"Per-cut vox verdicts over the word's rotations; reveals phase vs spectral invariants.","parameters":{"type":"object","properties":{"word":{"type":"string"}},"required":["word"]}}},
]

# ── corpus: structured-biased so T/banked/B are well represented ────────────
CURATED = ["⊢⊙∈≻⊤≺⊥∋⋈⊞◻⊣","⊢⊙∈≻⊤≺⊥∋⋈⊞◻◻◻◻◻◻◻◻⊢","⊙∈≻≻∋◻","⊙∈∋⊙",
           "⊢∈≻⊤≺⊥⋈⊞∋◻⊙⊣","⊢≻∈⊤⊥⊞∋⋈⊙≺◻⊣"]
def structured_word(rng):
    # scaffold that tends to fork, deposit the Belnap triple, and fuse
    core = ["⊢","⊙","∈","≻","⊤","≺","⊥","∋","⋈","⊞","◻","⊣"]
    rng.shuffle(core[2:-1])  # keep ⊢⊙ … ⊣ frame-ish, shuffle the middle
    return "".join(core)
def random_word(rng, lo=5, hi=13):
    return "".join(rng.choice(MARKS) for _ in range(rng.randint(lo,hi)))
def build_corpus(seed=1, n_struct=25, n_rand=15):
    rng = random.Random(seed); words=list(CURATED); seen=set(words)
    while len(words) < len(CURATED)+n_struct:
        w=structured_word(rng)
        if w not in seen: seen.add(w); words.append(w)
    while len(words) < len(CURATED)+n_struct+n_rand:
        w=random_word(rng)
        if w not in seen: seen.add(w); words.append(w)
    return words

# ── run + parse ─────────────────────────────────────────────────────────────
def run(cmds):
    return subprocess.run([RUN,*cmds],capture_output=True,text=True,timeout=1800).stdout
def blocks(out):
    return [(p.split("\n")[0].strip(), "\n".join(p.split("\n")[1:]).rstrip())
            for p in re.split(r"⊙> ",out)[1:]]
def clean(cmd,body):
    if cmd.startswith("imasm derive"):
        t=re.search(r"tuple:\s*(.+)",body); c=re.search(r"crystal:\s*(\d+)",body)
        return f"tuple: {t.group(1).strip()}  crystal: {c.group(1)}" if t and c else None
    if cmd.startswith("vox verdict"):
        m=re.search(r"verdict\s+(\w+)",body); return f"verdict {m.group(1)}" if m else None
    if cmd.startswith("banked"):
        return "\n".join(l.strip() for l in body.split("\n")
                         if l.strip() and not l.startswith("word")) or None
    if cmd.startswith("insert"):
        return "\n".join(l.strip() for l in body.split("\n")
                         if l.strip() and not l.startswith("word")) or None
    if cmd.startswith("weight"):
        return "\n".join(l.rstrip() for l in body.split("\n")
                         if re.search(r"final|surviving|deposits|stranded|cleared",l)) or None
    if cmd.startswith("cycle"):
        return "\n".join(l.rstrip() for l in body.split("\n")
                         if re.search(r"verdict|landing|PHASE|invariant|distinct",l))[:600] or None
    return None

def first_repair(insert_out):
    m=re.search(r"^\s*\S+ at\s+\d+\s+(\S+)",insert_out,re.M)
    return m.group(1) if m else None

VERB={"derive":"imasm derive","vox":"vox verdict","weight":"weight","banked":"banked",
      "insert":"insert","cycle":"cycle"}

def tool_msgs(tool, word, result):
    """assistant tool_call + tool response."""
    return [
        {"role":"assistant","content":"","tool_calls":[
            {"type":"function","function":{"name":tool,"arguments":json.dumps({"word":word})}}]},
        {"role":"tool","name":tool,"content":result},
    ]

def ex(user, turns):
    return {"tools":TOOLS,"messages":[{"role":"system","content":SYSTEM},
            {"role":"user","content":user}, *turns]}

def main():
    words=build_corpus()
    # pass 1: everything
    cmds=[f"{VERB[t]} {w}" for w in words for t in VERB]
    cache={}
    for cmd,body in blocks(run(cmds)):
        t=next((k for k,v in VERB.items() if cmd.startswith(v)),None)
        if not t: continue
        w=cmd[len(VERB[t]):].strip(); cache.setdefault(w,{})[t]=clean(cmd,body)
    # find leakers → repaired words, pass 2 for vox on the repair
    repairs={}
    for w in words:
        ins=cache.get(w,{}).get("insert","")
        bk=cache.get(w,{}).get("banked","")
        if ins and "exposed" in ins:
            g=first_repair(ins)
            if g: repairs[w]=None  # placeholder; repaired word built below
    # build repaired words: insert glyph at position from insert output
    rep_words={}
    for w in words:
        ins=cache.get(w,{}).get("insert","")
        m=re.search(r"^\s*(\S+) at\s+(\d+)\s+(\S+)",ins,re.M) if ins else None
        if m:
            rep_words[w]=m.group(3)  # the full repaired word is printed
    if rep_words:
        cmds2=[f"vox verdict {rw}" for rw in rep_words.values()]
        for cmd,body in blocks(run(cmds2)):
            if cmd.startswith("vox verdict"):
                rw=cmd[len("vox verdict"):].strip()
                cache.setdefault(rw,{})["vox"]=clean(cmd,body)

    out=[]
    # (1) single tool-call examples
    for w in words:
        c=cache.get(w,{})
        if c.get("derive"):
            out.append(ex(f"What tuple does {w} imscribe to?",
                          tool_msgs("derive",w,c["derive"])+
                          [{"role":"assistant","content":f"It imscribes to {c['derive']}."}]))
        if c.get("vox"):
            out.append(ex(f"What is the verdict of {w}?",
                          tool_msgs("vox",w,c["vox"])+
                          [{"role":"assistant","content":f"The word verdicts {c['vox'].split()[-1]}."}]))
    # (2) CHAINED: repair-and-recheck (banked → insert → vox on repair)
    for w, rw in rep_words.items():
        c=cache.get(w,{}); rc=cache.get(rw,{})
        if not (c.get("banked") and c.get("insert") and rc.get("vox")): continue
        verdict=rc["vox"].split()[-1]
        turns = (tool_msgs("banked",w,c["banked"]) +
                 tool_msgs("insert",w,c["insert"]) +
                 tool_msgs("vox",rw,rc["vox"]) +
                 [{"role":"assistant","content":
                   f"{w} leaks — its clear finds no holder behind it. The repair is one holding "
                   f"glyph: {rw}. Rechecked, the repair verdicts {verdict}: the four-valued weight "
                   f"now banks in a frame and is held as the both rather than lost in the open."}])
        out.append(ex(f"Does {w} hold? If not, repair it and tell me whether the repair changes "
                      f"the verdict.", turns))
    # (3) CHAINED: rotation-invariance (cycle → read)
    for w in words:
        cy=cache.get(w,{}).get("cycle")
        if cy and "verdict" in cy:
            out.append(ex(f"Is the verdict of {w} rotation-invariant, and is the register?",
                          tool_msgs("cycle",w,cy)+
                          [{"role":"assistant","content":
                            "Read the orbit: the vox verdict is the spectral (rotation-invariant) "
                            "reading; the final register is phase-bearing where it moves across cuts."}]))
    rng=random.Random(0); rng.shuffle(out)
    Path("chains_sample.jsonl").write_text("\n".join(json.dumps(r,ensure_ascii=False) for r in out)+"\n")
    from collections import Counter
    kinds=Counter("chain" if sum(1 for m in r["messages"] if m["role"]=="tool")>1 else "single" for r in out)
    print(f"emitted {len(out)} tool examples -> chains_sample.jsonl  ({dict(kinds)})")
    print(f"corpus {len(words)} words, {len(rep_words)} with repairs")

if __name__=="__main__":
    main()
